// Spawns a streak of d particles interpolated from va to vb.
void emit_sand_shark_dust_puffs_along_segment(void *moby, void *va_, void *vb_, int d, float fa, float fb) {
    float *va = va_;
    float *vb = vb_;
    float out[4];
    float tmp[4];
    float s[4];
    int i;
    float fd = d;
    float diff;
    float step;
    FastVecSub(out, vb, va);
    FastVecScale(out, out, 1.0f / fd);
    diff = fb - fa;
    *(u128b *)s = 0;
    s[2] = 0.01f;
    s[3] = 1.0f;
    step = diff / fd;
    for (i = 0; i < d; i++) {
        int a, c, col, r;
        float sp;
        char *p;
        FastVecScale(tmp, out, IntToFloat(i));
        FastVecAdd(tmp, va, tmp);
        a = rand_range(0x40, 0x70);
        c = rand_range(0x40, 0x7F);
        col = c | ((c << 16) | (c << 8));
        sp = random_float_between(1.0f, 1.02f);
        r = rand_range(-2, 2);
        s[0] = randf_sym(0.0f, 0.0025f);
        s[1] = randf_sym(0.0f, 0.0025f);
        s[2] = random_float_between(sand_shark_dust_rise_speed * 0.1f, sand_shark_dust_rise_speed);
        p = PartType23Spawn__s(tmp, sand_shark_dust_puff_size, 1.0f, sp, r, s, step + fa * 210000.0f, (a << 24) | col);
        if (p != 0) {
            char *q = p + 0x20;
            if (random_integer_below(2) != 0) {
                p[3] = 0x44;
            }
            *(unsigned short *)(p + 0xA) = sand_shark_dust_puff_ticks;
            *(int *)(q + 4) = 2;
            q[0xA] = a;
            q[0xB] = *(unsigned char *)&sand_shark_dust_puff_ticks;
        }
    }
}
