/* Path-following enemy: respawns at its home point on request, takes hits (dies and drops to the
   ground), then follows its path and retargets the hero when it strays. Adapted from Lombyte's project (GPL-3.0) for PAL: src/overlays/l02/gameplay/entities/002400c8.c, FUN_L02_002d5c88. */
void handle_sand_shark_damage_and_targeting(unsigned char *moby) {
    Vars_2D70C0 *d = ((Vars_2D70C0 *)((Moby *)moby)->pvars);
    char *h;
    int *path;
    int hit;
    float dmg;
    float k;
    float g;
    Vec4 p;
    Vec4 v;

    d->i280 = ((Moby *)moby)->state;
    if (((Moby *)moby)->state == 0) {
        return;
    }
    if (d->b2E == 2) {
        d->b2E = 1;
        if (d->i288 >= 0) {
            (*(Vars_2D70C0 **)((d->i288 << 8) + aridia_mobys_m + 0x78))->i14C -= 1;
        }
        if ((d->i27C = select_group_class_29c_moby(moby)) == 0) {
            DeleteMoby(moby);
            return;
        }
        ((Moby *)moby)->state = 0x1A;
        qcopy(moby + 0x10, d->home);
        *(int *)&((Moby *)moby)->collision = 0;
        ((Moby *)moby)->pos.z -= 10.0f;
    }
    if (d->i38 != 0 ||
        (!FastDecTimer(&d->t25C) && vec_distance_xy(moby + 0x10, &((Hero *)(hero_globals_base_r + 0xE1D))->motion.pos) < 10.0f)) {
        d->t25E = truncate_float_to_s32_r(multiply_global_factor(random_float_between(180.0f, 240.0f)));
    }
    d->i38 = 0;
    if (FastDecTimer(&d->t25E)) {
        d->f250 = d->f24C;
    } else {
        d->f250 = d->f24C + 5.0f;
    }
    dmg = 0.0f;
    h = MobyGetHitMessage(moby, 0x330000, 0);
    ComputeHitResponse(moby, h, &d->hp, 0, &hit, &dmg, 0, 4);
    if (hit != 1 && ((Moby *)moby)->state != 0x18) {
        extend_group_sand_shark_timers((char *)moby);
        d->i29C = 0;
        d->hp -= dmg;
        if (d->hp <= 0.0f) {
            d->hp -= dmg;
            d->i140 = 0x200;
            d->f130 = sand_shark_death_knockback_gravity_gp * g_frame_time_sq;
            d->f134 = sand_shark_death_knockback_horizontal_speed_approach_rate_gp * g_frame_time_sq;
            d->f138 = sand_shark_death_knockback_horizontal_speed_gp * g_frame_time;
            d->f13C = sand_shark_death_knockback_vertical_speed_gp * g_frame_time;
            d->b15D = 0;
            d->i144 = 9;
            d->f16C = 2.0f * g_frame_time;
            d->f148 = 0.5f;
            qcopy(&p, moby + 0x10);
            p.f[2] += 2.0f;
            g = ProbeGroundHeight(&p, 0, 0.5f);
            if (((Moby *)moby)->pos.z < g) {
                ((Moby *)moby)->pos.z = g;
            }
            if (d->i288 >= 0) {
                (*(Vars_2D70C0 **)((d->i288 << 8) + aridia_mobys_m + 0x78))->i14C -= 1;
                d->b15D = 0;
            } else {
                p.f[2] += 0.01f;
            }
            d->i144 |= 0x20;
            ((Moby *)moby)->flags &= 0xEFFF;
            v.q = *(u128_2D70C0 *)(h + 0x10);
            HeadingFromVector(&v, &k, &d->f138, &d->f13C);
            InitKnockback(k, moby, d->knock, 6, 1, 0);
            d->f148 = 0.85f;
            d->f170 = 7.0f;
            d->f174 = 14.0f;
            ((Moby *)moby)->state = 0x18;
            *(int *)&((Moby *)moby)->collision = 0;
            d->b117 = 0x78;
            RerollEffectCounter(moby, d->anim);
        }
    }
    ((Moby *)moby)->hit_slot = 0xFF;
    StepColorFade(moby, d->anim);
    path = aridia_paths_r[d->i290];
    if (FindNearestEligibleMoby(d->f250, moby, d->tgt, 0, 0, path + 4, *path) != 2 &&
        (d->f250 < vec_distance_xy(d->home, d->tgt) ||
         FastAbsF(((Moby *)moby)->pos.z - d->tgt[2]) > 3.0f)) {
        d->i214 = 2;
    }
    if (d->i210 == 0) {
        Hero *hero = (Hero *)(hero_globals_base_r + 0xE1D);
        d->i210 = (int)((void *)hero->moby);
        qcopy(d->tgt, hero->motion.pos.f);
    }
}
