/* Hit reaction: takes damage, flinches or dies (knocked away from the hero), then retargets.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l02/gameplay/entities/002400c8.c, FUN_L02_002d85b8. */
void handle_level02_bot_damage_and_retargeting(void *arg) {
    char *moby = arg;
    Vars85b8 *d = ((Vars85b8 *)((Moby *)moby)->pvars);
    char *h;
    char *t;
    int target[20];
    int hit;
    float dmg;

    dmg = 0.0f;
    h = MobyGetHitMessage(moby, 0x330000, 0);
    if (h != 0 && *(short *)(*(char **)(h + 0x20) + 0xA6) == 0x264) {
        h = 0;
    }
    ComputeHitResponse(moby, h, &d->hp, 0, &hit, &dmg, 0, 4);
    if (hit != 1 && ((unsigned char *)moby)[0x20] != 0x11) {
        d->hp -= dmg;
        d->i90 = truncate_float_to_s32(614.4f);
        d->f98 = 0.6f;
        if (0.0f < d->hp) {
            if (dmg < 1.0f) {
                d->flash = 100;
            } else {
                void *k = d->knock;
                d->flash = 0x78;
                d->f80 = D_L02_00161B14_D99F0 * g_frame_time_sq;
                d->f84 = D_L02_00161B08_D99F0 * g_frame_time_sq;
                d->f88 = D_L02_00161AFC_D99F0 * g_frame_time;
                d->f8C = D_L02_00161B00_D99F0 * g_frame_time;
                d->fBC = D_L02_00161B2C_D99F0 * g_frame_time;
                d->fA0 = 0.5f;
                d->i94 = 25;
                d->bAD = 0;
                InitKnockback(fast_atan2(((Moby *)moby)->pos.x - g_hero_r.motion.pos.f[0],
                                              ((Moby *)moby)->pos.y - g_hero_r.motion.pos.f[1]),
                                 moby, k, 0xB, 1, 0);
                d->fC0 = 6.5f;
                d->fC4 = 11.0f;
                moby[0x20] = 0x10;
            }
        } else {
            void *k2 = d->knock;
            d->f80 = D_L02_00161B14_D99F0 * g_frame_time_sq;
            d->f84 = D_L02_00161B04_D99F0 * g_frame_time_sq;
            d->f88 = D_L02_00161AF4_D99F0 * g_frame_time;
            d->f8C = D_L02_00161AF8_D99F0 * g_frame_time;
            d->fBC = D_L02_00161B2C_D99F0 * g_frame_time;
            d->i94 = 9;
            d->bAD = 0;
            InitKnockback(fast_atan2(((Moby *)moby)->pos.x - g_hero_r.motion.pos.f[0],
                                          ((Moby *)moby)->pos.y - g_hero_r.motion.pos.f[1]),
                             moby, k2, 0xE, 1, 0);
            d->fC0 = 6.5f;
            d->fC4 = 13.0f;
            ((Moby *)moby)->flags &= 0xEFFF;
            d->flash = 0xFA;
            moby[0x20] = 0x11;
        }
        RerollEffectCounter(moby, d->anim);
    }
    ((unsigned char *)moby)[0xA4] = 0xFF;
    t = d->target;
    if (t == 0 || t[0x20] < 0 ||
        (*(short *)(t + 0xA6) != 0x10E && *(short *)(t + 0xA6) != 0xCB && *(short *)(t + 0xA6) != 0) ||
        ((unsigned char *)moby)[0x20] != 0xC) {
        FindNearestTargetMoby(moby, (char *)target, 14.0f);
        d->target = (char *)target[16];
    }
    if (d->target == 0) {
        d->target = *(char **)g_hero_moby;
    }
    StepColorFade(moby, d->anim);
}
